function drawMonsterLabels(ctx, labels, fxTime) {
  if (!Array.isArray(labels) || labels.length <= 0) return;
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'bottom';
  ctx.font = canvasFont('0.15px', 600);
  for (let i = 0; i < labels.length; i++) {
    const rec = labels[i];
    if (!rec) continue;
    // Offset label Y based on creature scale so it sits above the glyph
    const ss = rec.sizeScale || 1;
    const y = rec.y - (0.30 + 0.22 * ss);
    ctx.strokeStyle = 'rgba(0,0,0,0.7)';
    ctx.lineWidth = 0.04;
    ctx.strokeText(rec.text, rec.x, y);
    ctx.fillStyle = rec.color;
    ctx.fillText(rec.text, rec.x, y);
  }
  ctx.restore();
}

function drawPersistentTargetLock(ctx, entities, fxTime) {
  if (!Array.isArray(entities)) return;
  for (let i = 0; i < entities.length; i++) {
    const entity = entities[i];
    if (!entity?.targetLocked) continue;
    const x = Number(entity.pos?.x);
    const y = Number(entity.pos?.y);
    if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
    const pulse = 0.55 + 0.45 * Math.sin(fxTime * 6.5 + (entity.id | 0));
    const w = 0.42;
    const h = 0.48;
    const len = 0.14;
    ctx.save();
    ctx.strokeStyle = `rgba(80,220,255,${(0.42 + pulse * 0.22).toFixed(3)})`;
    ctx.lineWidth = 0.035;
    ctx.beginPath();
    ctx.moveTo(x - w, y - h + len); ctx.lineTo(x - w, y - h); ctx.lineTo(x - w + len, y - h);
    ctx.moveTo(x + w - len, y - h); ctx.lineTo(x + w, y - h); ctx.lineTo(x + w, y - h + len);
    ctx.moveTo(x - w, y + h - len); ctx.lineTo(x - w, y + h); ctx.lineTo(x - w + len, y + h);
    ctx.moveTo(x + w - len, y + h); ctx.lineTo(x + w, y + h); ctx.lineTo(x + w, y + h - len);
    ctx.stroke();
    ctx.restore();
  }
}

